Implement simple ItemChecker:

class ItemChecker:
    def __init__(self, feed_options):
        self.accepted_items = []
        # feed_options may have 'item_classes' key: tuple of item classes
        ic = feed_options.get('item_classes')
        if ic:
            self.accepted_items.extend(ic)

    def accepts(self, item):
        return self.accepts_class(item) and self.accepts_fields(self._item_fields(item))

    def accepts_class(self, item):
        if not self.accepted_items:
            return True
        # item can be dict or object with fields
        return any(isinstance(item, cls) for cls in self.accepted_items)

    def accepts_fields(self, fields):
        # default accept all
        return True

    def _item_fields(self, item):
        # return dict of fields: for dict it's itself; for Item, use item.fields keys with values possibly.
        if isinstance(item, dict):
            return item
        # assume Item or dataclass etc. Use dict(item) if possible
        try:
            return dict(item)
        except Exception:
            # fallback: get attributes?
            return {}

But for default behavior we can simply ignore fields.

Simplify: accepts just returns accepts_class.

